
import React, { useEffect, useRef, useState } from "react";
import * as faceapi from "face-api.js";
import { Document, Page, pdfjs } from "react-pdf";
import "react-pdf/dist/esm/Page/AnnotationLayer.css";

// Configurar el worker de PDF.js
pdfjs.GlobalWorkerOptions.workerSrc = `https://cdnjs.cloudflare.com/ajax/libs/pdf.js/3.11.174/pdf.worker.min.js`;

const Home = () => {
  const videoRef = useRef(null);
  const [status, setStatus] = useState("🔄 Iniciando cámara...");
  const [pdfPage, setPdfPage] = useState(1);
  const [numPages, setNumPages] = useState(null);

  const lastMove = useRef(Date.now());

  // 👉 Cargar modelos de face-api.js
  useEffect(() => {
    const loadModels = async () => {
      const MODEL_URL = process.env.PUBLIC_URL + "/models";
      await faceapi.nets.tinyFaceDetector.loadFromUri(MODEL_URL);
      await faceapi.nets.faceLandmark68TinyNet.loadFromUri(MODEL_URL);
    };

    loadModels();
  }, []);

  // 👉 Activar cámara y analizar movimiento
  useEffect(() => {
    const startCamera = async () => {
      try {
        const stream = await navigator.mediaDevices.getUserMedia({
          video: { width: 640, height: 480, facingMode: "user" },
          audio: false,
        });

        const video = videoRef.current;
        video.srcObject = stream;
        video.onloadedmetadata = () => {
          video.play().then(() => {
            setStatus("✅ Cámara activa");
            detectarMovimiento();
          });
        };
      } catch (err) {
        console.error("Error cámara:", err);
        setStatus("❌ No se pudo acceder a la cámara");
      }
    };

    const detectarMovimiento = async () => {
      const video = videoRef.current;

      const options = new faceapi.TinyFaceDetectorOptions({ inputSize: 160 });
      setInterval(async () => {
        if (!video || video.paused || video.ended) return;

        const result = await faceapi
          .detectSingleFace(video, options)
          .withFaceLandmarks(true);

        if (result && result.landmarks) {
          const nose = result.landmarks.getNose()[3]; // punto central de la nariz
          const x = nose.x;

          const now = Date.now();
          if (now - lastMove.current > 1500) {
            if (x < 220 && pdfPage < numPages) {
              setPdfPage((p) => p + 1); // cabeza a la derecha
              lastMove.current = now;
            } else if (x > 420 && pdfPage > 1) {
              setPdfPage((p) => p - 1); // cabeza a la izquierda
              lastMove.current = now;
            }
          }
        }
      }, 500);
    };

    startCamera();
  }, [numPages, pdfPage]);

  return (
    <div style={{ textAlign: "center", padding: "20px" }}>
      <h2>🧠 Navegación PDF con movimientos de cabeza</h2>
      <p>{status}</p>

      <video
        ref={videoRef}
        autoPlay
        muted
        playsInline
        width="320"
        height="240"
        style={{ border: "2px solid #ccc", marginBottom: "10px" }}
      />

      <div style={{ width: "90%", margin: "auto" }}>
        <Document
          file="/folklore.pdf"
          onLoadSuccess={({ numPages }) => setNumPages(numPages)}
        >
          <Page pageNumber={pdfPage} width={600} />
        </Document>
        <p>
          Página {pdfPage} de {numPages || "?"}
        </p>
      </div>
    </div>
  );
};

export { Home };
